import { useEffect, useState } from 'preact/hooks';

import Popover from '../../../../../shared/Popover';
import Button from '../../../../../shared/Button';

import styles from './styles.module.scss';
import { UserDb } from '../../../../user/slice/types';
import { FunctionalComponent } from 'preact';

interface Props {
  onClose: () => unknown,
  friend: UserDb,
  selectedRef: Record<string, HTMLElement>,
}

const NewFriend: FunctionalComponent<Props> = ({ onClose, friend, selectedRef }: Props) => {
  const [ref, setRef] = useState(selectedRef[friend.id]);

  useEffect(() => {
    if (ref) return () => null;

    const interval = setInterval(() => {
      setRef((prev) => {
        const newRef = prev || selectedRef[friend.id];
        if (newRef) window.clearInterval(interval);
        return newRef;
      });
    }, 300);
    return () => window.clearInterval(interval);
  }, []);

  return (
    <div className={styles.newFriendContainer}>
      <Popover
        onClose={onClose}
        anchorEl={ref}
        className={styles.newFriendPopover}
      >
        <p className={styles.text}>
          Hooray! <b>{friend.name}</b> is now your friend. Why don’t you say
          hello with a GIF?
        </p>

        <video
          src="https://assets.oceanhero.today/extension/friends/friends-onboarding-2.mp4"
          loop
          muted
          autoPlay
        />

        <div>
          <Button variant="primary" size="large" onClick={onClose}>
            Close
          </Button>
        </div>
      </Popover>
    </div>
  );
};

export default NewFriend;
